def protenix_panel():
    source=R/'results/study-package/protenix-diagnostic-summary.json'
    if not source.exists():return ''
    summary=json.loads(source.read_text())
    figure='<img class="figure" src="assets/protenix-base-diagnostic.png" alt="Protenix base diagnostic contact recovery and core RMSD">' if (D/'assets/protenix-base-diagnostic.png').exists() else ''
    status_names={'failed_before_prediction':'failed before prediction','failed_with_partial_outputs':'failed with partial outputs','returned_without_expected_outputs':'returned without expected outputs','pending_or_unreturned':'pending','completed':'completed','missing':'not returned'}
    rows=[]
    for item in summary.get('attempts',[]):
        label=html_escape(item.get('label') or item.get('run_id') or 'Protenix')
        status=html_escape(status_names.get(item.get('status'),item.get('status') or 'unknown'))
        model=html_escape(item.get('model') or 'not returned')
        count=html_escape(str(item.get('prediction_cif_count',0)))
        note=html_escape(item.get('error') or 'No candidate gate change')
        rows.append(f'<tr><td>{label}</td><td>{status}</td><td>{model}</td><td>{count}</td><td>{note}</td></tr>')
    return '<div class="card" style="margin-top:18px"><div class="card-top"><h3>Protenix diagnostic addendum</h3><span class="tag">NO GATE CHANGE</span></div><table><thead><tr><th>Attempt</th><th>Status</th><th>Model</th><th>CIFs</th><th>Note</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table>'+figure+'<div class="caption">Independent model-family check. It cannot override the failed Boltz control gates. <a href="reports/protenix-diagnostic-summary.md">Read receipt ↗</a></div></div>'
extra='<section id="package"><div class="section-head"><h2>Inspect the study package.</h2><span class="tag">RECORDED RESULTS</span></div><div class="files">'+''.join(submission)+'<a href="data/pose-audit.csv">All-seed structural audit ↗</a><a href="data/experimental-control-candidates.csv">Literature benchmark candidates ↗</a></div><div class="card"><img class="figure" src="assets/positive-pose-audit.png" alt="All six positive-control predictions: native-contact recovery and target-fitted core RMSD"><div class="caption">41 experimental residue contacts at a 5 Å heavy-atom cutoff. All seeds retained. Custom contact recovery is not binding affinity or a new selection gate.</div></div>'+protenix_panel()+'</section>'
html=html.replace('<footer>',extra+'<footer>')
